cd /app && timeout 120 python3 << 'EOF'
import numpy as np, itertools
q=np.array([5.426070e-05,1.038196e-04,1.779558e-04,3.294836e-04])
lines={'D':1350,'G':1580,"D'":1620,'2D':2700,'D+G':2950,"G'":3240,'Si':520,'D+D"':2450}
names=list(lines); vals=np.array([lines[k] for k in names])
best=[]
for i in range(len(q)):
    for j in range(len(q)):
        if i==j: continue
        for a in range(len(vals)):
            for b in range(len(vals)):
                if a==b: continue
                # nu = A*q + B
                A=(vals[a]-vals[b])/(q[i]-q[j]); B=vals[b]-A*q[j]
                pred=A*q+B
                # match each predicted to nearest line, count good
                used=set(); score=0; detail=[]
                for k,p in enumerate(pred):
                    d=np.abs(vals-p); m=d.argmin()
                    if d[m]<60 and m not in used:
                        used.add(m); score+=1; detail.append((round(p),names[m],round(d[m],1)))
                    else:
                        detail.append((round(p),'?',round(d.min())))
                best.append((score,A,B,i,j,a,b,detail))
best.sort(key=lambda t:-t[0])
for t in best[:10]:
    print(t[0], round(t[1],1), round(t[2]), t[3],t[4],t[5],t[6], t[7])
EOF
